async function showOrder(id){try{const o=await api(`orders/detail&id=${id}`),closed=['paid','void','refunded'].includes(o.status),unsent=o.items.some(i=>Number(i.quantity)>Number(i.sent_quantity)),netPaid=Number(o.paid);openModal(`Order ${o.number}`,`<div class="order-detail-head"><div>${badge(o.status)} ${o.fulfillment_status?badge(o.fulfillment_status):''}<p>${esc(o.customer_name||o.table_name||'Walk-in')} · ${esc(o.type.replaceAll('_',' '))}</p><small class="muted">${date(o.created_at)}${o.due_at?' · Pickup '+date(o.due_at):''}</small></div><div class="order-detail-total"><span>Total</span><strong>${money(o.total)}</strong></div></div>${o.notes?`<div class="notice">${esc(o.notes)}</div>`:''}<div class="table-wrap"><table><thead><tr><th>Item</th><th>Quantity</th><th>To kitchen</th><th>Amount</th></tr></thead><tbody>${o.items.map(i=>`<tr><td><strong>${esc(i.name)}</strong>${i.note?`<small>${esc(i.note)}</small>`:''}</td><td>${num(i.quantity)}</td><td>${num(i.sent_quantity||0)} sent</td><td>${money(i.line_total??(i.quantity*i.price))}</td></tr>`).join('')}</tbody></table></div><div class="detail-totals"><div class="total-row"><span>Subtotal</span><span>${money(o.subtotal)}</span></div><div class="total-row"><span>Discount</span><span>−${money(o.discount)}</span></div><div class="total-row"><span>${Number(o.tax_enabled)?'Tax':'Tax-free bill'}</span><span>${money(o.tax)}</span></div><div class="total-row"><span>Received</span><span>${money(o.gross_paid??(Number(o.paid)+Number(o.refunded||0)))}</span></div>${Number(o.refunded)?`<div class="total-row"><span>Refunded</span><span>${money(o.refunded)}</span></div>`:''}<div class="total-row grand-total"><span>Balance due</span><strong>${money(o.balance??(o.total-o.paid))}</strong></div></div><div class="button-row detail-actions">${!closed?`<button type="button" class="button btn-secondary" id="detail-edit">${icon('edit')} Edit order</button><button type="button" class="button btn-primary" id="detail-pay">${icon('wallet')} Payment / deposit</button>`:''}${unsent&&!['void','refunded'].includes(o.status)?'<button type="button" class="button btn-secondary" id="detail-send">Send to kitchen</button>':''}${o.fulfillment_status==='kitchen'?'<button type="button" class="button btn-secondary" id="detail-ready">Mark ready</button>':''}<button type="button" class="button btn-secondary" id="detail-slip">View order slip</button><button type="button" class="button btn-secondary" id="detail-print-slip">${icon('print')} Print slip</button>${o.invoice_number?`<button type="button" class="button btn-secondary" id="detail-invoice">View invoice</button><button type="button" class="button btn-secondary" id="detail-reprint">${icon('print')} Reprint invoice</button>`:''}${manager()&&netPaid>0?'<button type="button" class="button btn-ghost" id="detail-refund">Refund</button>':''}${manager()&&!['void','refunded'].includes(o.status)?'<button type="button" class="button btn-danger" id="detail-void">Void order</button>':''}</div><div class="detail-section"><h3>Payment history</h3>${o.payments?.length?`<div class="table-wrap"><table><thead><tr><th>Method</th><th>Amount</th><th>Reference</th><th>Time</th></tr></thead><tbody>${o.payments.map(p=>`<tr><td>${esc(p.method)}${p.type==='refund'?' · Refund':''}</td><td>${money(p.amount)}</td><td>${esc(p.reference||'—')}</td><td>${date(p.created_at)}</td></tr>`).join('')}</tbody></table></div>`:'<p class="muted">No payments yet.</p>'}</div><div class="detail-section"><h3>Kitchen tickets</h3>${o.tickets?.length?o.tickets.map(t=>`<div class="list-row"><div><strong>KOT ${esc(t.number||t.id)}</strong><small class="muted">${date(t.created_at)}</small></div><button type="button" class="button btn-ghost btn-small" data-ticket="${t.id}">${icon('print')} View ticket</button></div>`).join(''):'<p class="muted">No items sent to the kitchen yet.</p>'}</div><p class="hint">Preparation consumes recipe stock. Refunds and voids do not put prepared ingredients back in inventory.</p>`,async()=>{},'Close',true);$('#detail-edit')?.addEventListener('click',()=>{closeModal();if(state.cart.length&&state.dirty&&state.order?.id!==o.id){confirm('Switch to this order?','Your current cart has unsaved changes. Switching will discard those changes; saved orders remain available.',async()=>{loadOrder(o);navigate('pos');});}else{loadOrder(o);navigate('pos');}});$('#detail-pay')?.addEventListener('click',()=>{closeModal();paymentModal(id).catch(e=>notify(e.message,true));});$('#detail-send')?.addEventListener('click',()=>{closeModal();confirm('Send to kitchen?',`Send all unsent items on ${o.number} to the kitchen and deduct their recipe ingredients from stock.`,async()=>{await api('orders/send',{id});notify('Kitchen ticket queued. Stock updated.');await renderPage();});});$('#detail-ready')?.addEventListener('click',()=>{closeModal();setReady(id);});$('#detail-slip').onclick=()=>printSlip('preorder',id);$('#detail-print-slip').onclick=()=>queueSlip('preorder',id);$('#detail-reprint')?.addEventListener('click',()=>{closeModal();confirm('Reprint this invoice?','A final invoice is already queued automatically when the order is fully paid. Check the customer printer before issuing a duplicate.',async()=>{await api('print/queue',{kind:'invoice',id,confirm_duplicate_risk:true});notify('Invoice reprint queued for the customer printer.');});});$('#detail-invoice')?.addEventListener('click',()=>printSlip('invoice',id));$$('[data-ticket]').forEach(b=>b.onclick=()=>printSlip('kot',id,b.dataset.ticket));$('#detail-refund')?.addEventListener('click',()=>{closeModal();refundModal(o);});$('#detail-void')?.addEventListener('click',()=>{closeModal();openModal('Void order',`<p class="muted">${esc(o.number)}. Refund any received payments first. Prepared ingredients stay consumed.</p>${field('Reason','reason','','text','required maxlength="300"')}`,async f=>{await api('orders/void',{id,reason:f.get('reason')});notify('Order voided.');if(state.order?.id===id)loadOrder(await api(`orders/detail&id=${id}`));await renderPage();},'Void order');});}catch(e){notify(e.message,true);}}
function refundModal(o){const requestId=crypto.randomUUID();openModal('Record a refund',`<div class="notice">Refundable received payments: <strong>${money(Number(o.paid))}</strong>. Complete the cash or bank refund yourself, then record it here.</div><div class="form-grid">${field('Refund amount','amount',((Number(o.paid))/100).toFixed(2),'number','required min="0.01" step="0.01"')}<label class="field"><span>Refund method</span><select name="method"><option value="cash">Cash</option><option value="easypaisa">Easypaisa</option><option value="jazzcash">JazzCash</option><option value="bank">Bank transfer</option></select></label></div>${field('Reason / transaction reference','reason','','text','required maxlength="300"')}<p class="hint">Refunds reduce collections and appear in reports. Prepared stock remains consumed.</p>`,async f=>{await api('orders/refund',{id:o.id,request_id:requestId,amount:toMinor(f.get('amount')),method:f.get('method'),reason:f.get('reason')});notify('Refund recorded.');if(state.order?.id===o.id)loadOrder(await api(`orders/detail&id=${o.id}`));await renderPage();},'Record refund');}
async function setReady(id){try{await api('orders/status',{id,status:'ready'});notify('Order marked ready.');await renderPage();}catch(e){notify(e.message,true);}}
async function renderKitchen(){const orders=await api('kitchen');$('#page-content').innerHTML=pageHeader('THE HEART OF YOUR CAFÉ','In the kitchen.','Live preparation tickets. Refresh to see newly sent items.',`<button class="button btn-secondary" id="kitchen-refresh">${icon('refresh')} Refresh tickets</button>`)+`<div class="kitchen-grid">${orders.length?orders.map(o=>`<article class="kitchen-card panel ${o.fulfillment_status==='ready'?'kitchen-ready':''}"><div class="ticket-header"><div><span class="eyebrow">${esc(o.type.replaceAll('_',' '))}</span><h2>${esc(o.number)}</h2><p>${esc(o.table_name||o.customer_name||'Walk-in')}</p></div>${badge(o.fulfillment_status||o.status)}</div>${o.due_at?`<div class="ticket-due">${icon('calendar')} Pickup ${date(o.due_at)}</div>`:''}<div class="ticket-lines">${o.items.filter(i=>Number(i.sent_quantity)>0).map(i=>`<div class="ticket-line"><strong class="ticket-qty">${num(i.sent_quantity)}×</strong><div><strong>${esc(i.name)}</strong>${i.note?`<p class="ticket-note">${esc(i.note)}</p>`:''}</div></div>`).join('')}</div>${o.notes?`<div class="notice">${esc(o.notes)}</div>`:''}<div class="ticket-footer"><small>${date(o.created_at)}</small><div class="button-row"><button class="button btn-ghost btn-small" data-kitchen-detail="${o.id}">Details</button>${o.fulfillment_status!=='ready'?`<button class="button btn-primary btn-small" data-ready="${o.id}">${icon('check')} Mark ready</button>`:badge('ready')}</div></div></article>`).join(''):empty('A calm kitchen','Orders appear here when items are sent to the kitchen.')}</div><p class="hint">Kitchen tickets include preparation notes and quantities; prices stay on the customer receipt.</p>`;$('#kitchen-refresh').onclick=renderKitchen;$$('[data-ready]').forEach(b=>b.onclick=()=>setReady(Number(b.dataset.ready)));$$('[data-kitchen-detail]').forEach(b=>b.onclick=()=>showOrder(Number(b.dataset.kitchenDetail)));}
async function renderInventory(){const inv=await api('inventory');state.inventory=inv;const low=inv.items.filter(i=>Number(i.active)&&i.on_hand<=i.min_stock);$('#page-content').innerHTML=pageHeader('KNOW WHAT’S IN YOUR PANTRY','A well-stocked kind of day.','Track ingredients, deliveries, waste and actual stock counts.',`<button class="button btn-secondary" id="inventory-suppliers">Suppliers</button><button class="button btn-primary" id="stock-add">${icon('plus')} Add raw item</button>`)+`<div class="stats-grid">${stat('Raw items',num(inv.items.filter(i=>Number(i.active)).length),'Your active pantry and ingredients','stock')}${stat('Low stock alerts',num(low.length),'At or below your minimum level','alert',low.length?'stat-warning':'')}${stat('Estimated stock value',money(inv.items.reduce((s,i)=>s+Math.round(i.on_hand*i.avg_cost),0)),'Weighted average purchase cost','wallet')}</div><section class="panel"><div class="panel-head"><div><h2>Pantry & raw stock</h2><p class="muted">Recipes use the same units you set here.</p></div><label class="search-field">${icon('search')}<input type="search" id="stock-search" aria-label="Search inventory" placeholder="Search ingredients…"></label></div><div id="stock-list"></div></section><section class="panel inventory-ledger"><div class="panel-head"><div><h2>Recent stock movements</h2><p class="muted">Every change leaves a trail.</p></div><button class="button btn-ghost btn-small" id="inventory-reports">Full reconciliation ${icon('chevron')}</button></div>${inv.movements.length?`<div class="table-wrap"><table><thead><tr><th>Ingredient</th><th>Movement</th><th>Quantity</th><th>Cost</th><th>Reference</th><th>Time</th></tr></thead><tbody>${inv.movements.map(m=>`<tr><td>${esc(m.item_name)}</td><td>${badge(m.type)}</td><td>${Number(m.quantity)>0?'+':''}${num(m.quantity)}</td><td>${money(m.cost_total||0)}</td><td>${esc(m.reference||'—')}</td><td>${date(m.created_at)}</td></tr>`).join('')}</tbody></table></div>`:empty('No stock movements yet','Receive an opening delivery to start tracking your stock.')}</section>`;const draw=()=>{const q=$('#stock-search').value.toLowerCase();const items=inv.items.filter(i=>!q||i.name.toLowerCase().includes(q));$('#stock-list').innerHTML=items.length?`<div class="table-wrap"><table><thead><tr><th>Item</th><th>On hand</th><th>Minimum</th><th>Average cost / unit</th><th>Status</th><th>Actions</th></tr></thead><tbody>${items.map(i=>`<tr><td><strong>${esc(i.name)}</strong><small>${esc(i.unit)}</small></td><td><strong class="${i.on_hand<=i.min_stock?'text-warning':''}">${num(i.on_hand)} ${esc(i.unit)}</strong></td><td>${num(i.min_stock)} ${esc(i.unit)}</td><td>${money(i.avg_cost)}</td><td>${!Number(i.active)?badge('archived'):i.on_hand<=i.min_stock?badge('low stock'):badge('in stock')}</td><td><div class="button-row"><button class="button btn-secondary btn-small" data-stock-move="${i.id}">Movement</button><button class="button btn-ghost btn-small" data-stock-edit="${i.id}" aria-label="Edit ${esc(i.name)}">${icon('edit')}</button></div></td></tr>`).join('')}</tbody></table></div>`:empty('Your pantry starts here','Add ingredients, packaging and other raw items, then receive opening stock.');$$('[data-stock-edit]').forEach(b=>b.onclick=()=>stockItemModal(inv.items.find(i=>i.id==b.dataset.stockEdit)));$$('[data-stock-move]').forEach(b=>b.onclick=()=>stockMoveModal(inv.items.find(i=>i.id==b.dataset.stockMove)));};$('#stock-add').onclick=()=>stockItemModal();$('#stock-search').oninput=draw;$('#inventory-reports').onclick=()=>navigate('reports');$('#inventory-suppliers').onclick=showSuppliers;draw();}
function stockItemModal(i=null){openModal(i?'Edit raw item':'Add raw item',`<div class="form-grid">${field('Item name','name',i?.name||'','text','required maxlength="100"')}<label class="field"><span>Stock unit</span><select name="unit" ${i?'disabled':''}>${['g','ml','pcs','kg','l'].map(u=>`<option value="${u}" ${i?.unit===u?'selected':''}>${u==='g'?'g · grams':u==='ml'?'ml · millilitres':u==='pcs'?'pcs · individual pieces':u==='kg'?'kg · kilograms':'l · litres'}</option>`).join('')}</select></label>${field('Low-stock threshold','min_stock',i?.min_stock||0,'number','min="0" step="0.001" required')}</div><label class="checkbox-field"><input type="checkbox" name="active" ${!i||Number(i.active)?'checked':''}> Active in your pantry</label><p class="hint">Use grams or millilitres for recipe precision. Stock and recipe quantities must use this exact unit. Add quantities through Movement after saving.</p>`,async f=>{await api('inventory/item',{...(i?{id:i.id}:{}),name:f.get('name'),unit:i?.unit||f.get('unit'),min_stock:Number(f.get('min_stock')),active:f.has('active')});notify('Raw item saved.');await renderInventory();});}
function stockMoveModal(i){openModal(`Stock movement · ${i.name}`,`<div class="notice">On hand: <strong>${num(i.on_hand)} ${esc(i.unit)}</strong></div><div class="form-grid"><label class="field"><span>Movement</span><select name="type" id="stock-move-type"><option value="receive">Receive delivery / opening stock</option><option value="waste">Record waste</option><option value="count">Reconcile actual count</option></select></label>${field('Quantity ('+i.unit+')','quantity','','number','min="0" step="0.001" required id="stock-move-qty"')}${field('Total purchase cost','cost_total','','number','min="0" step="0.01" id="stock-move-cost"')}${field('Supplier / reason / reference','reference','','text','required maxlength="250"')}</div><p class="hint" id="stock-move-hint">Enter delivered quantity and the total cost of this delivery.</p>`,async f=>{const type=f.get('type');await api('inventory/move',{stock_item_id:i.id,type,quantity:Number(f.get('quantity')),cost_total:type==='receive'?toMinor(f.get('cost_total')||0):0,reference:f.get('reference')});notify('Stock movement recorded.');await renderInventory();},'Record movement');$('#stock-move-type').onchange=e=>{const type=e.target.value;$('#stock-move-cost').closest('label').hidden=type!=='receive';$('#stock-move-qty').min=type==='count'?'0':'0.001';$('#stock-move-hint').textContent=type==='count'?'Enter the actual counted quantity remaining. The ledger records the difference.':type==='waste'?'Enter the quantity being discarded. Add a reason so you can review waste later.':'Enter delivered quantity and the total cost of this delivery.';};}
async function showSuppliers(){try{const suppliers=await api('suppliers');openModal('Suppliers',`${suppliers.length?suppliers.map(s=>`<div class="list-row"><div><strong>${esc(s.name)}</strong><p class="muted">${esc(s.phone||'No contact number')}</p></div><button type="button" class="button btn-secondary btn-small" data-supplier-edit="${s.id}">Edit</button></div>`).join(''):'<p class="muted">Save supplier details for your pantry deliveries.</p>'}<button type="button" class="button btn-primary" id="supplier-add">${icon('plus')} Add supplier</button>`,async()=>{},'Close');const edit=s=>{closeModal();openModal(s?'Edit supplier':'Add supplier',`<div class="form-grid">${field('Supplier name','name',s?.name||'','text','required maxlength="100"')}${field('Contact number','phone',s?.phone||'','tel','maxlength="60"')}</div>`,async f=>{await api('suppliers',{...(s?{id:s.id}:{}),name:f.get('name'),phone:f.get('phone')});notify('Supplier saved.');});};$('#supplier-add').onclick=()=>edit(null);$$('[data-supplier-edit]').forEach(b=>b.onclick=()=>edit(suppliers.find(s=>s.id==b.dataset.supplierEdit)));}catch(e){notify(e.message,true);}}
async function renderMenu(){const [menu,inv]=await Promise.all([api('menu'),api('inventory')]);state.menu=menu;state.inventory=inv;$('#page-content').innerHTML=pageHeader('MAKE YOUR MENU YOUR OWN','Good food. Thoughtful recipes.','Add as many menu items and categories as your café needs.',`<button class="button btn-secondary" id="category-add">${icon('plus')} Add category</button><button class="button btn-primary" id="menu-add">${icon('plus')} Add menu item</button>`)+`<section class="panel"><div class="panel-head"><div><h2>Your menu</h2><p class="muted">Recipe quantities are consumed when items go to the kitchen.</p></div><label class="search-field">${icon('search')}<input id="menu-admin-search" type="search" aria-label="Search menu items" placeholder="Search your menu…"></label></div><div class="category-summary">${menu.categories.length?menu.categories.map(c=>`<span class="badge badge-muted">${esc(c.name)}</span>`).join(''):'<p class="muted">Start by adding a category such as Coffee or Breakfast.</p>'}</div><div id="menu-admin-list"></div></section><div class="notice menu-recipe-notice">${icon('stock')}<div><strong>A recipe for accurate stock.</strong><p>Add the raw ingredients and packaging used in one portion. Stock units and recipe units must match. Items with no recipe can sell without consuming inventory.</p></div></div>`;const draw=()=>{const q=$('#menu-admin-search').value.toLowerCase(),list=menu.items.filter(i=>!q||i.name.toLowerCase().includes(q));$('#menu-admin-list').innerHTML=list.length?`<div class="table-wrap"><table><thead><tr><th>Menu item</th><th>Category</th><th>Price</th><th>Item tax</th><th>Recipe</th><th>Status</th><th></th></tr></thead><tbody>${list.map(i=>`<tr><td><strong>${esc(i.name)}</strong><small>${esc(i.description||'')}</small></td><td>${esc(menu.categories.find(c=>c.id==i.category_id)?.name||'—')}</td><td>${money(i.price)}</td><td>${num(i.tax_rate)}%</td><td>${i.recipe.length?`<span>${i.recipe.length} ingredient${i.recipe.length>1?'s':''}</span>`:'<span class="text-warning">No stock recipe</span>'}</td><td>${badge(Number(i.active)?'active':'archived')}</td><td><button class="button btn-secondary btn-small" data-menu-edit="${i.id}">${icon('edit')} Edit</button></td></tr>`).join('')}</tbody></table></div>`:empty('Let’s build your menu','Add a category and your first menu item. You can create recipes as your pantry grows.');$$('[data-menu-edit]').forEach(b=>b.onclick=()=>menuItemModal(menu.items.find(i=>i.id==b.dataset.menuEdit)));};$('#menu-admin-search').oninput=draw;$('#category-add').onclick=()=>openModal('Add a menu category',field('Category name','name','','text','required maxlength="80" placeholder="e.g. Coffee & drinks"'),async f=>{await api('categories',{name:f.get('name')});notify('Category added.');await renderMenu();});$('#menu-add').onclick=()=>menuItemModal();draw();}
function menuItemModal(i=null){const stocks=state.inventory.items.filter(s=>Number(s.active)),categories=state.menu.categories;if(!categories.length){notify('Add a menu category first.',true);return;}let recipe=(i?.recipe||[]).map(r=>({...r}));openModal(i?'Edit menu item':'Add menu item',`<div class="form-grid">${field('Menu item name','name',i?.name||'','text','required maxlength="120"')}<label class="field"><span>Category</span><select name="category_id">${categories.map(c=>`<option value="${c.id}" ${i?.category_id==c.id?'selected':''}>${esc(c.name)}</option>`).join('')}</select></label>${field('Selling price','price',((i?.price||0)/100).toFixed(2),'number','required min="0" step="0.01"')}${field('Item tax rate (%)','tax_rate',i?.tax_rate??session.settings?.default_tax_rate??0,'number','required min="0" max="100" step="0.01"')}<label class="field full-width"><span>Description / allergens</span><textarea name="description" rows="2" maxlength="500" placeholder="A short description, ingredients or allergy information">${esc(i?.description||'')}</textarea></label></div><label class="checkbox-field"><input type="checkbox" name="active" ${!i||Number(i.active)?'checked':''}> Show on the POS menu</label><div class="recipe-heading"><div><h3>Recipe for one serving</h3><p class="hint">Enter ingredients in their stock unit. Example: milk 200 ml, beans 18 g.</p></div><button type="button" class="button btn-secondary btn-small" id="recipe-add" ${!stocks.length?'disabled':''}>${icon('plus')} Ingredient</button></div><div id="recipe-rows"></div>${!stocks.length?'<div class="notice">Add raw items in Inventory to build a stock recipe.</div>':''}`,async f=>{recipe.forEach(r=>{if(!r.stock_item_id||!Number.isFinite(Number(r.quantity))||Number(r.quantity)<=0)throw new Error('Each recipe ingredient needs a positive quantity.');});if(new Set(recipe.map(r=>Number(r.stock_item_id))).size!==recipe.length)throw new Error('Use each ingredient once per recipe.');await api('menu',{...(i?{id:i.id}:{}),name:f.get('name'),category_id:Number(f.get('category_id')),price:toMinor(f.get('price')),tax_rate:Number(f.get('tax_rate')),description:f.get('description'),active:f.has('active'),recipe:recipe.map(r=>({stock_item_id:Number(r.stock_item_id),quantity:Number(r.quantity)}))});notify('Menu item and recipe saved.');await renderMenu();},'Save menu item',true);const draw=()=>{$('#recipe-rows').innerHTML=recipe.length?recipe.map((r,n)=>`<div class="recipe-row"><label class="field"><span>Ingredient ${n+1}</span><select data-recipe-stock="${n}" required>${stocks.map(s=>`<option value="${s.id}" ${r.stock_item_id==s.id?'selected':''}>${esc(s.name)} (${esc(s.unit)})</option>`).join('')}</select></label><label class="field"><span>Quantity per serving</span><input type="number" data-recipe-qty="${n}" value="${esc(r.quantity)}" min="0.001" step="0.001" required></label><span class="recipe-unit">${esc(stocks.find(s=>s.id==r.stock_item_id)?.unit||'')}</span><button type="button" class="button btn-ghost icon-button" data-recipe-remove="${n}" aria-label="Remove ingredient ${n+1}">${icon('trash')}</button></div>`).join(''):'<p class="muted recipe-empty">No ingredients added. This item will not consume inventory.</p>';$$('[data-recipe-stock]').forEach(s=>s.onchange=()=>{recipe[Number(s.dataset.recipeStock)].stock_item_id=Number(s.value);draw();});$$('[data-recipe-qty]').forEach(s=>s.oninput=()=>{recipe[Number(s.dataset.recipeQty)].quantity=Number(s.value);});$$('[data-recipe-remove]').forEach(b=>b.onclick=()=>{recipe.splice(Number(b.dataset.recipeRemove),1);draw();});};$('#recipe-add').onclick=()=>{const unused=stocks.find(s=>!recipe.some(r=>r.stock_item_id==s.id));if(!unused){notify('All active ingredients are already in this recipe.');return;}recipe.push({stock_item_id:unused.id,quantity:1});draw();};draw();}
let reportPreset='today',reportFrom='',reportTo='',lastReport=null;
function reportDates(preset){const day=today(),[y,m]=day.split('-').map(Number);if(preset==='today')return [day,day];if(preset==='month')return [`${y}-${String(m).padStart(2,'0')}-01`,day];if(preset==='half')return [`${y}-${m<=6?'01':'07'}-01`,day];if(preset==='year')return [`${y}-01-01`,day];return [reportFrom||day,reportTo||day];}
async function renderReports(){[reportFrom,reportTo]=reportDates(reportPreset);const [r,expenses]=await Promise.all([api(`reports&from=${reportFrom}&to=${reportTo}`),api('expenses')]);lastReport=r;const rangeExpenses=expenses.filter(e=>e.date>=reportFrom&&e.date<=reportTo);$('#page-content').innerHTML=pageHeader('THE BIG PICTURE, SIMPLY','Know how your café is doing.','Sales, payments, costs and ingredient reconciliation in one statement.',`<button class="button btn-secondary" id="export-report">${icon('download')} Export CSV</button><button class="button btn-secondary" id="print-report">${icon('print')} Print statement</button><button class="button btn-primary" id="expense-add">${icon('plus')} Add expense</button>`)+`<section class="panel report-toolbar"><div class="tabs">${[['today','Today'],['month','This month'],['half','This half-year'],['year','This year'],['custom','Custom']].map(([p,l])=>`<button class="pill ${reportPreset===p?'active':''}" data-report-preset="${p}">${l}</button>`).join('')}</div><form id="report-range"><label class="field compact"><span>From</span><input type="date" name="from" value="${reportFrom}" required></label><label class="field compact"><span>To</span><input type="date" name="to" value="${reportTo}" required></label><button class="button btn-secondary" type="submit">Apply</button></form></section><div class="stats-grid report-stats">${stat('Net invoiced sales',money(r.net_sales),`${num(r.orders)} finalized orders · after refunds`,'wallet')}${stat('Payments collected',money(r.collected),'Includes deposits; net of refunds','orders')}${stat('Estimated operating profit',money(r.profit_estimate),'After tax, ingredients, waste & expenses','reports')}${stat('Tax collected (net)',money(r.tax),'Tax amounts after proportional refunds','stock')}</div><div class="report-grid"><section class="panel"><div class="panel-head"><div><h2>Sales over time</h2><p class="muted">${date(reportFrom,false)} – ${date(reportTo,false)}</p></div><span class="badge badge-muted">${r.daily.length} days</span></div>${renderChart(r.daily)}<div class="report-key"><span><i class="chart-key"></i> Finalized sales</span><span class="muted">Sales and collections can differ when deposits or refunds cross dates.</span></div></section><section class="panel"><div class="panel-head"><div><h2>Payment reconciliation</h2><p class="muted">Compare these with cash and account statements.</p></div></div><div class="payment-breakdown">${r.payment_totals.length?r.payment_totals.map(p=>`<div class="list-row"><div class="payment-method"><span class="method-symbol">${icon(p.method==='cash'?'wallet':'orders')}</span><strong>${esc(p.method==='bank'?'Bank transfer':p.method==='jazzcash'?'JazzCash':p.method==='easypaisa'?'Easypaisa':'Cash')}</strong></div><strong>${money(p.total)}</strong></div>`).join(''):'<p class="muted">No collections for these dates.</p>'}<div class="total-row grand-total"><strong>Net collected</strong><strong>${money(r.collected)}</strong></div></div></section></div><div class="report-grid"><section class="panel"><div class="panel-head"><div><h2>Statement summary</h2><p class="muted">Costs follow ingredient usage dates.</p></div></div><div class="statement-lines">${[['Gross invoiced sales',r.sales],['Refunds',-r.refunds],['Net invoiced sales',r.net_sales],['Net tax',-r.tax],['Ingredients used (COGS)',-r.cogs],['Waste cost',-(r.waste_cost||0)],['Operating expenses',-r.expenses],['Estimated operating profit',r.profit_estimate]].map(([label,v],n)=>`<div class="total-row ${n===7?'grand-total':''}"><span>${label}</span><strong>${money(v)}</strong></div>`).join('')}</div></section><section class="panel"><div class="panel-head"><div><h2>Popular on the menu</h2><p class="muted">Finalized sales, after order discounts.</p></div></div>${r.top_items.length?`<div class="table-wrap"><table><thead><tr><th>Item</th><th>Quantity</th><th>Sales</th></tr></thead><tbody>${r.top_items.map(i=>`<tr><td>${esc(i.name)}</td><td>${num(i.quantity)}</td><td>${money(i.sales)}</td></tr>`).join('')}</tbody></table></div>`:empty('No sales yet','Your best sellers will appear after finalizing orders.')}</section></div><section class="panel"><div class="panel-head"><div><h2>Inventory reconciliation</h2><p class="muted">Opening + received − used − waste + adjustments = closing.</p></div></div>${r.stock.length?`<div class="table-wrap"><table><thead><tr><th>Ingredient</th><th>Opening</th><th>Received</th><th>Used in orders</th><th>Waste</th><th>Adjustment</th><th>Closing</th><th>Closing value</th></tr></thead><tbody>${r.stock.map(s=>`<tr><td><strong>${esc(s.name)}</strong><small>${esc(s.unit)}</small></td><td>${num(s.opening)}</td><td>${num(s.received)}</td><td>${num(s.used)}</td><td>${num(s.waste)}</td><td>${num(s.adjustment)}</td><td><strong>${num(s.closing)}</strong></td><td>${money(s.value)}</td></tr>`).join('')}</tbody></table></div>`:empty('No stock to reconcile','Add your ingredients in Inventory.')}</section><section class="panel"><div class="panel-head"><div><h2>Daily sales statement</h2><p class="muted">Daily figures for the selected period.</p></div></div><div class="table-wrap report-daily-table"><table><thead><tr><th>Date</th><th>Orders</th><th>Sales</th><th>Refunds</th><th>Net sales</th></tr></thead><tbody>${r.daily.filter(d=>d.orders||d.sales||d.refunds).length?r.daily.filter(d=>d.orders||d.sales||d.refunds).map(d=>`<tr><td>${date(d.date,false)}</td><td>${num(d.orders)}</td><td>${money(d.sales)}</td><td>${money(d.refunds)}</td><td><strong>${money(d.net_sales)}</strong></td></tr>`).join(''):'<tr><td colspan="5" class="muted">No sales or refunds in this period.</td></tr>'}</tbody></table></div></section><section class="panel"><div class="panel-head"><div><h2>Operating expenses</h2><p class="muted">Recorded expenses for the selected dates.</p></div></div>${rangeExpenses.length?`<div class="table-wrap"><table><thead><tr><th>Date</th><th>Category</th><th>Note</th><th>Method</th><th>Amount</th></tr></thead><tbody>${rangeExpenses.map(e=>`<tr><td>${date(e.date,false)}</td><td>${esc(e.category)}</td><td>${esc(e.note||'—')}</td><td>${esc(e.method||'cash')}</td><td>${money(e.amount)}</td></tr>`).join('')}</tbody></table></div>`:empty('No expenses recorded','Add rent, utilities and other café expenses to include them in your estimate.')}</section><div class="notice"><strong>How this statement works</strong><p>${esc(r.basis||'Finalized invoices count as sales. Deposits count as payments. Recipe ingredients are consumed when orders are sent to the kitchen. Profit is an estimate, not a complete accounting statement.')}</p></div>`;$$('[data-report-preset]').forEach(b=>b.onclick=()=>{reportPreset=b.dataset.reportPreset;renderReports().catch(e=>notify(e.message,true));});$('#report-range').onsubmit=e=>{e.preventDefault();const f=new FormData(e.currentTarget);reportFrom=String(f.get('from'));reportTo=String(f.get('to'));if(reportFrom>reportTo){notify('The start date must be on or before the end date.',true);return;}reportPreset='custom';renderReports().catch(err=>notify(err.message,true));};$('#export-report').onclick=()=>exportReport(r);$('#print-report').onclick=()=>window.print();$('#expense-add').onclick=expenseModal;}
function renderChart(daily){if(!daily.some(d=>d.sales))return empty('The next sale starts the story','Finalized sales will appear here.');let points=daily.length>31?daily.filter((d,i)=>i%Math.ceil(daily.length/31)===0).map((d,i,arr)=>{const start=daily.indexOf(d),end=start+Math.ceil(daily.length/31);return {...d,sales:daily.slice(start,end).reduce((s,x)=>s+x.sales,0)};}):daily;const max=Math.max(...points.map(d=>d.sales),1);return `<div class="sales-chart" role="img" aria-label="Sales chart from ${esc(reportFrom)} to ${esc(reportTo)}"><div class="chart-axis"><span>${money(max)}</span><span>${money(0)}</span></div><div class="chart-bars">${points.map(d=>`<div class="chart-column" title="${esc(d.date)}: ${esc(money(d.sales))}"><div class="chart-bar chart-h-${Math.max(1,Math.round(d.sales/max*10))}"></div><span>${esc(d.date.slice(5))}</span></div>`).join('')}</div></div>`;}
function csv(rows,name){const safe=v=>{if(typeof v==='number')return String(v);let s=String(v??'');if(/^[=+@\-\t\r]/.test(s))s="'"+s;return '"'+s.replaceAll('"','""')+'"';};const blob=new Blob(['\ufeff'+rows.map(r=>r.map(safe).join(',')).join('\r\n')],{type:'text/csv;charset=utf-8;'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);notify('Statement exported.');}
function exportReport(r){const rows=[['CAFE STATEMENT',session.settings.cafe_name],['Period',reportFrom,reportTo],['Currency',session.settings.currency||'PKR'],[],['SUMMARY','Amount'],...['sales','refunds','net_sales','tax','collected','expenses','cogs','waste_cost','profit_estimate'].map(k=>[k.replaceAll('_',' '),(r[k]||0)/100]),[],['PAYMENT RECONCILIATION'],['Method','Net received'],...r.payment_totals.map(p=>[p.method,p.total/100]),[],['DAILY SALES'],['Date','Orders','Sales','Refunds','Net sales'],...r.daily.map(d=>[d.date,d.orders,d.sales/100,d.refunds/100,d.net_sales/100]),[],['STOCK RECONCILIATION'],['Item','Unit','Opening','Received','Used','Waste','Adjustments','Closing','Value'],...r.stock.map(s=>[s.name,s.unit,s.opening,s.received,s.used,s.waste,s.adjustment,s.closing,s.value/100]),[],['TOP ITEMS'],['Item','Quantity','Sales'],...r.top_items.map(i=>[i.name,i.quantity,i.sales/100]),[],['Basis',r.basis||'']];csv(rows,`cafe-statement-${reportFrom}-to-${reportTo}.csv`);}
function expenseModal(){openModal('Record operating expense',`<div class="form-grid">${field('Expense date','date',today(),'date','required')}${field('Amount','amount','','number','required min="0.01" step="0.01"')}${field('Category','category','','text','required maxlength="80" placeholder="e.g. Utilities, rent, maintenance"')}<label class="field"><span>Paid from</span><select name="method"><option value="cash">Cash drawer</option><option value="bank">Bank</option><option value="easypaisa">Easypaisa</option><option value="jazzcash">JazzCash</option></select></label><label class="field full-width"><span>Note / reference</span><textarea name="note" rows="2" maxlength="500"></textarea></label></div><p class="hint">Cash expenses are deducted from the current cash shift. Stock deliveries belong in Inventory rather than operating expenses.</p>`,async f=>{await api('expenses',{amount:toMinor(f.get('amount')),date:f.get('date'),category:f.get('category'),method:f.get('method'),note:f.get('note')});notify('Expense recorded.');await renderReports();},'Record expense');}
async function renderShifts(){const s=await api('shifts'),c=s.current;$('#page-content').innerHTML=pageHeader('FROM OPENING TO CLOSING','A balanced end to the day.','Count the drawer, track cash movements and reconcile your shift.',c?'<span class="badge badge-success">Register open</span>':'<button class="button btn-primary" id="shift-open">Open cash register</button>')+(c?`<div class="stats-grid">${stat('Opening float',money(c.opening_cash),`Opened ${date(c.opened_at)}`,'wallet')}${stat('Net cash payments',money(c.cash_payments||0),'Cash received minus cash refunds','orders')}${stat('Cash expenses',money(c.cash_expenses||0),'Expenses recorded during this shift','stock')}${stat('Expected in drawer',money(c.expected_cash),'Opening + payments − expenses','shift')}</div><section class="panel shift-active"><div><span class="eyebrow">SHIFT #${c.id}</span><h2>Your register is open.</h2><p class="muted">Count all cash in the drawer before closing. Any difference is saved for review.</p></div><button class="button btn-primary" id="shift-close">${icon('check')} Count & close register</button></section>`:`<section class="panel">${empty('Start with your opening float','Open a shift before taking cash payments. Enter the change you put in the drawer.','<button class="button btn-primary" id="shift-open-empty">Open cash register</button>')}</section>`)+`<section class="panel"><div class="panel-head"><div><h2>Previous shifts</h2><p class="muted">Your register history and cash differences.</p></div></div>${s.history.length?`<div class="table-wrap"><table><thead><tr><th>Shift</th><th>Opened</th><th>Closed</th><th>Float</th><th>Expected</th><th>Counted</th><th>Difference</th><th>Note</th></tr></thead><tbody>${s.history.map(h=>`<tr><td>#${h.id}</td><td>${date(h.opened_at)}</td><td>${date(h.closed_at)}</td><td>${money(h.opening_cash)}</td><td>${money(h.expected_cash)}</td><td>${h.counted_cash==null?'—':money(h.counted_cash)}</td><td><strong class="${h.discrepancy?'text-warning':'text-success'}">${h.discrepancy==null?'—':money(h.discrepancy)}</strong></td><td>${esc(h.note||'—')}</td></tr>`).join('')}</tbody></table></div>`:empty('No shifts closed yet','Closed shifts and cash differences appear here.')}</section><div class="notice"><strong>Keep QR transfers separate.</strong><p>Easypaisa, JazzCash and bank payments reconcile against their account statements. They do not change expected cash in your drawer.</p></div>`;const open=()=>openModal('Open cash register',field('Opening cash float','opening_cash','0.00','number','required min="0" step="0.01"')+'<p class="hint">Count the cash set aside for change before the first transaction.</p>',async f=>{await api('shifts/open',{opening_cash:toMinor(f.get('opening_cash'))});notify('Cash register opened.');await renderShifts();},'Open register');$('#shift-open')?.addEventListener('click',open);$('#shift-open-empty')?.addEventListener('click',open);$('#shift-close')?.addEventListener('click',()=>openModal('Count & close the register',`<div class="notice">Expected cash: <strong>${money(c.expected_cash)}</strong></div>${field('Actual cash counted','counted_cash','','number','required min="0" step="0.01" id="shift-count"')}<div id="shift-difference" class="cash-difference" aria-live="polite"></div><label class="field"><span>Closing note / reason for any difference</span><textarea name="note" rows="3" maxlength="500"></textarea></label>`,async f=>{await api('shifts/close',{counted_cash:toMinor(f.get('counted_cash')),note:f.get('note')});notify('Cash register closed. Reconciliation saved.');await renderShifts();},'Close register'));$('#shift-close')?.addEventListener('click',()=>{$('#shift-count').oninput=e=>{$('#shift-difference').textContent=`Difference: ${money(Math.round((Number(e.target.value)||0)*100)-Number(c.expected_cash))}`;};});}
document.addEventListener('keydown',e=>{if(e.key==='Escape' && $('#modal-form'))closeModal();if(e.key==='/'&&state.page==='pos'&&!['INPUT','TEXTAREA','SELECT'].includes(document.activeElement.tagName)){e.preventDefault();$('#menu-search')?.focus();}if(e.key==='Tab'&&$('#modal-form')){const focusable=$$('button:not([disabled]), input:not([disabled]), textarea:not([disabled]), select:not([disabled]), a[href]',$('.modal')).filter(x=>!x.hidden&&x.getClientRects().length);const first=focusable[0],last=focusable.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus();}}});
window.addEventListener('beforeunload',e=>{if(state.cart.length&&(state.dirty||!state.order)){e.preventDefault();e.returnValue='';}});
const initial=location.hash.slice(1);if(initial)state.page=initial;
